import itertools

def de_bruijn(k, n):
    # Create a list to store the De Bruijn sequence
    sequence = [0] * (k ** n)

    # Create a dictionary to store the graph
    graph = {i: [] for i in range(k ** n)}

    # Populate the graph
    for i in range(k ** n):
        for j in range(k):
            # Calculate the next node
            next_node = (i * k + j) % (k ** n)
            graph[i].append(next_node)

    # Perform an Eulerian tour
    def eulerian_tour(graph, start):
        tour = []
        stack = [start]
        while stack:
            node = stack[-1]
            if graph[node]:
                next_node = graph[node].pop()
                stack.append(next_node)
            else:
                tour.append(stack.pop())
        return tour

    # Generate the De Bruijn sequence
    tour = eulerian_tour(graph, 0)
    for i in range(len(tour)):
        sequence[i] = tour[i] % k

    return sequence

