# Function to generate a schedule
def generate_schedule(week, golfers_left):
    if week == weeks:
        return True

    for p in permutations(golfers_left):
        groups = [list(p[i:i+4]) for i in range(0, len(p), 4)]
        valid = True

        # Check if any pair of golfers has been in the same group before
        for i in range(groups):
            for j in range(i+1, groups):
                for golfer1 in groups[i]:
                    for golfer2 in groups[j]:
                        if has_been_together(golfer1, golfer2, week):
                            valid = False
                            break
                if not valid:
                    break
            if not valid:
                break

        if valid:
            schedule[week] = groups
            new_golfers_left = [golfer for golfer in golfers_left]
            for group in groups:
                for golfer in group:
                    new_golfers_left.remove(golfer)

            if generate_schedule(week+1, new_golfers_left):
                return True

    return False

